type Currency = 'EGP' | 'AED' | 'SAR' | 'JOD' | 'GBP' | 'EUR' | 'USD' | 'CAD';
type Coupon = { kind: 'percent'; percentOff: number } | { kind: 'free-shipping' };

const COUNTRIES = ['EG', 'AE', 'SA', 'JO', 'GB', 'DE', 'US', 'CA'] as const;
type Country = (typeof COUNTRIES)[number];

const currencyByCountry = {
  EG: 'EGP',
  AE: 'AED',
  SA: 'SAR',
  JO: 'JOD',
  GB: 'GBP',
  DE: 'EUR',
  US: 'USD',
  CA: 'CAD',
} as const satisfies Record<Country, Currency>;

const coupons = {
  WELCOME10: { kind: 'percent', percentOff: 10 },
  SPRING15: { kind: 'percent', percentOff: 15 },
  FREESHIP: { kind: 'free-shipping' },
} satisfies Record<string, Coupon>;

function isCountry(value: string): value is Country {
  return (COUNTRIES as readonly string[]).includes(value);
}

function currencyFor(country: Country): Currency {
  return currencyByCountry[country];
}

// ---- Type tests (do not edit) ----
type T1 = Expect<Equal<Country, 'EG' | 'AE' | 'SA' | 'JO' | 'GB' | 'DE' | 'US' | 'CA'>>;
type T2 = Expect<Equal<(typeof currencyByCountry)['DE'], 'EUR'>>;
type T3 = Expect<Equal<keyof typeof coupons, 'WELCOME10' | 'SPRING15' | 'FREESHIP'>>;
type T4 = Expect<Equal<(typeof coupons)['SPRING15']['percentOff'], number>>;

// @ts-expect-error: France is not a Cartwheel country
currencyByCountry.FR;

// @ts-expect-error: typo in the coupon code
coupons.SPRNG15;

console.log(currencyFor('DE'), isCountry('EG'), isCountry('FR'));
